{
 "summary": "The file states two results. The first is that there exist a connected bipartite 2-degenerate graph H on Fin q, with every 2-coloring having max degree > 2 on each side, and constants c, ε > 0 such that ex(n,H) ≥ c·n^{3/2+ε} for all large n. The second is that Erdős's degeneracy conjecture (ex(n,H) = O(n^{2−1/r}) for bipartite r-degenerate H) is false. The main caveat is the elaboration of the exponent `(3 : ℕ) / 2 + ε`, which should read 3/2 + ε in ℝ but is worth a probe. The extra side-degree clause only makes the first theorem stronger.",
 "glossary": [
  {"decl": "TwoDegenerateGraphs.neighborsWithin", "line": 8, "plain": "The set of neighbours of v inside the finset s.", "standard_concept": "N(v) ∩ s", "matches_standard": "yes", "note": ""},
  {"decl": "TwoDegenerateGraphs.IsDegenerate", "line": 13, "plain": "Every nonempty vertex set s contains a vertex with at most r neighbours inside s.", "standard_concept": "r-degenerate graph (every nonempty subgraph has a vertex of degree ≤ r)", "matches_standard": "yes", "note": "It is phrased via induced subgraphs on finsets, which is equivalent to the subgraph formulation."},
  {"decl": "TwoDegenerateGraphs.IsTwoDegenerate", "line": 17, "plain": "IsDegenerate with r = 2.", "standard_concept": "2-degenerate graph", "matches_standard": "yes", "note": ""},
  {"decl": "TwoDegenerateGraphs.DegeneracyConjectureStatement", "line": 20, "plain": "For all r > 0 and every bipartite r-degenerate graph H on Fin q, ex(n,H) = O(n^{2−1/r}) as n → ∞.", "standard_concept": "Erdős's degeneracy conjecture (3) in the paper", "matches_standard": "yes", "note": "The exponent is written explicitly as ((2:ℕ):ℝ) − 1/(r:ℝ), so there is no truncation. Taking H on Fin q covers every finite graph up to isomorphism."},
  {"decl": "SimpleGraph.extremalNumber (Mathlib)", "line": 24, "plain": "The maximum number of edges of an H-free simple graph on n vertices.", "standard_concept": "ex(n,H)", "matches_standard": "yes", "note": "Mathlib's H-free is non-induced subgraph containment, as in the paper. Not inspected here, but this is the standard Mathlib definition."}
 ],
 "lean_claims": [
  {"theorem": "TwoDegenerateGraphs.twoDegenerateExtremalCounterexample", "line": 28, "plain": "There exist q and a simple graph H on Fin q that is connected, bipartite and 2-degenerate. For every proper 2-coloring of H and each side, the maximum degree of H over the vertices on that side is > 2. There also exist real c, ε > 0 such that for all sufficiently large n, c·n^{3/2+ε} ≤ ex(n,H)."},
  {"theorem": "TwoDegenerateGraphs.not_erdos_146", "line": 43, "plain": "It is not the case that for all r > 0, q and bipartite r-degenerate H on Fin q, ex(n,H) = O(n^{2−1/r}) as n → ∞."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist a fixed connected bipartite 2-degenerate graph H and constants c, ε > 0 with ex(n,H) ≥ c·n^{3/2+ε} for all sufficiently large n."},
  {"ref": "Section 1.2 / abstract", "plain": "Erdős's conjecture (3) that every bipartite r-degenerate H has ex(n,H) = O(n^{2−1/r}) is false, already for r = 2."}
 ],
